/**
 * Persistent conversations (0.5.0).
 *
 * Storage only: this service never calls a model. Titles are derived from the
 * first user message (truncated) rather than generated by an extra inference,
 * so saving a conversation costs nothing and cannot fail because a provider is
 * down.
 *
 * Every read and write is scoped to the active profile.
 */
import type {
  ConversationListRow,
  ConversationMessageRecord,
  ConversationRecord
} from '../context/sqlite-store'
import type {
  ConversationDetail,
  ConversationMessageInfo,
  ConversationSummary
} from '../../../shared/protocol'

export interface ConversationStore {
  createConversation(c: ConversationRecord): void
  listConversations(profileId: string, query: string, includeArchived: boolean): ConversationListRow[]
  getConversation(conversationId: string): ConversationRecord | null
  listConversationMessages(conversationId: string): ConversationMessageRecord[]
  appendConversationMessage(m: ConversationMessageRecord): void
  renameConversation(conversationId: string, title: string, updatedAt: string): boolean
  setConversationArchived(conversationId: string, archived: boolean, updatedAt: string): boolean
  setConversationPinned(conversationId: string, pinned: boolean, updatedAt: string): boolean
  deleteConversation(conversationId: string): boolean
}

export interface ConversationDeps {
  store: ConversationStore
  getProfileId: () => string
  now?: () => Date
  idFactory?: () => string
}

const DEFAULT_TITLE = 'New conversation'
export const MAX_TITLE = 80

/** Title from the first user message: trimmed, single line, bounded. */
export function deriveTitle(text: string): string {
  const clean = text.replace(/\s+/g, ' ').trim()
  if (clean.length === 0) return DEFAULT_TITLE
  return clean.length > MAX_TITLE ? `${clean.slice(0, MAX_TITLE - 1)}…` : clean
}

function toSummary(row: ConversationListRow): ConversationSummary {
  return {
    conversationId: row.conversationId,
    title: row.title,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    messageCount: row.messageCount,
    archived: row.archived,
    pinned: row.pinned,
    preview: row.preview
  }
}

function toMessageInfo(m: ConversationMessageRecord): ConversationMessageInfo {
  return {
    messageId: m.messageId,
    role: m.role,
    content: m.content,
    createdAt: m.createdAt,
    ...(m.providerLabel ? { providerLabel: m.providerLabel } : {}),
    ...(m.model ? { model: m.model } : {})
  }
}

export class ConversationService {
  constructor(private readonly deps: ConversationDeps) {}

  list(query = '', includeArchived = false): ConversationSummary[] {
    return this.deps.store
      .listConversations(this.deps.getProfileId(), query, includeArchived)
      .map(toSummary)
  }

  create(title?: string): ConversationSummary {
    const now = (this.deps.now?.() ?? new Date()).toISOString()
    const record: ConversationRecord = {
      conversationId: this.deps.idFactory?.() ?? `conv-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      profileId: this.deps.getProfileId(),
      title: title?.trim() ? title.trim().slice(0, 120) : DEFAULT_TITLE,
      archived: false,
      pinned: false,
      createdAt: now,
      updatedAt: now
    }
    this.deps.store.createConversation(record)
    return toSummary({ ...record, messageCount: 0, preview: '' })
  }

  get(conversationId: string): ConversationDetail | null {
    const record = this.deps.store.getConversation(conversationId)
    if (!record || record.profileId !== this.deps.getProfileId()) return null
    const messages = this.deps.store.listConversationMessages(conversationId).map(toMessageInfo)
    const preview = messages.length > 0 ? messages[messages.length - 1].content.slice(0, 160) : ''
    return {
      conversationId: record.conversationId,
      title: record.title,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt,
      messageCount: messages.length,
      archived: record.archived,
      pinned: record.pinned,
      preview,
      messages
    }
  }

  append(req: {
    conversationId: string
    role: 'user' | 'assistant'
    content: string
    providerLabel?: string
    model?: string
  }): { ok: boolean; messageId?: string; message?: string } {
    const record = this.deps.store.getConversation(req.conversationId)
    if (!record || record.profileId !== this.deps.getProfileId()) {
      return { ok: false, message: 'Unknown conversation' }
    }
    const content = req.content.trim()
    if (content.length === 0) return { ok: false, message: 'Empty message' }
    const now = (this.deps.now?.() ?? new Date()).toISOString()
    const messageId = `msg-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`
    this.deps.store.appendConversationMessage({
      messageId,
      conversationId: req.conversationId,
      role: req.role,
      content,
      providerLabel: req.providerLabel ?? null,
      model: req.model ?? null,
      createdAt: now
    })
    // First user message names the conversation, unless the user already did.
    if (req.role === 'user' && record.title === DEFAULT_TITLE) {
      this.deps.store.renameConversation(req.conversationId, deriveTitle(content), now)
    }
    return { ok: true, messageId }
  }

  rename(conversationId: string, title: string): boolean {
    const record = this.deps.store.getConversation(conversationId)
    if (!record || record.profileId !== this.deps.getProfileId()) return false
    const clean = title.replace(/\s+/g, ' ').trim().slice(0, 120)
    if (clean.length === 0) return false
    return this.deps.store.renameConversation(conversationId, clean, (this.deps.now?.() ?? new Date()).toISOString())
  }

  remove(conversationId: string): boolean {
    const record = this.deps.store.getConversation(conversationId)
    if (!record || record.profileId !== this.deps.getProfileId()) return false
    return this.deps.store.deleteConversation(conversationId)
  }

  setArchived(conversationId: string, archived: boolean): boolean {
    const record = this.deps.store.getConversation(conversationId)
    if (!record || record.profileId !== this.deps.getProfileId()) return false
    return this.deps.store.setConversationArchived(
      conversationId,
      archived,
      (this.deps.now?.() ?? new Date()).toISOString()
    )
  }

  setPinned(conversationId: string, pinned: boolean): boolean {
    const record = this.deps.store.getConversation(conversationId)
    if (!record || record.profileId !== this.deps.getProfileId()) return false
    return this.deps.store.setConversationPinned(
      conversationId,
      pinned,
      (this.deps.now?.() ?? new Date()).toISOString()
    )
  }
}
